from AlgorithmImports import *
from datetime import datetime, timedelta, time
from collections import deque


class SpyFiveMinuteCallAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda u: u.IncludeWeeklys()
                       .Strikes(-200, 200)
                       .Expiration(0, 365)
        )

        self.closes = deque(maxlen=20)
        self.bucket = None
        self.pending_signal = None

        self.entry_ticket = None
        self.entry_symbol = None
        self.entry_price = None
        self.exit_ticket = None
        self.expiration_stop_day = None
        self.expiration_processed_day = None

    def OnData(self, slice: Slice):
        self._update_five_minute_bar(slice)

        # Process an entry only once, immediately after an eligible
        # completed five-minute bar, using the current Slice's option chain.
        if self.pending_signal is not None:
            signal_time = self.pending_signal
            self.pending_signal = None
            self._try_enter(slice, signal_time)

        self._process_expiration_safety()
        self._process_time_stop(slice)
        self._process_profit_target(slice)

    def _update_five_minute_bar(self, slice: Slice):
        if not slice.Bars.ContainsKey(self.spy_symbol):
            return

        minute_bar = slice.Bars[self.spy_symbol]
        ny_time = minute_bar.EndTime

        # The minute bar's EndTime is used to align completed bars. A bar
        # ending at 09:35 represents the 09:30–09:35 interval.
        if ny_time.tzinfo is not None:
            ny_time = ny_time.replace(tzinfo=None)

        if ny_time.time() < time(9, 30) or ny_time.time() > time(16, 0):
            return

        bucket_end = ny_time.replace(
            minute=(ny_time.minute // 5) * 5,
            second=0,
            microsecond=0
        )

        if self.bucket is None:
            self.bucket = {
                "end": bucket_end,
                "bars": [minute_bar]
            }
            return

        if bucket_end == self.bucket["end"]:
            self.bucket["bars"].append(minute_bar)
            return

        self._complete_bucket()

        # A gap discards the incomplete bucket and starts a new one.
        self.bucket = {
            "end": bucket_end,
            "bars": [minute_bar]
        }

    def _complete_bucket(self):
        if self.bucket is None:
            return

        bars = self.bucket["bars"]
        end_time = self.bucket["end"]

        # Never synthesize a five-minute bar from incomplete minute data.
        if len(bars) != 5:
            self.bucket = None
            return

        close = bars[-1].Close
        self.closes.append(float(close))

        if len(self.closes) >= 20:
            fast_previous = sum(list(self.closes)[-6:-1]) / 5
            slow_previous = sum(list(self.closes)[-21:-1]) / 20
            fast_current = sum(list(self.closes)[-5:]) / 5
            slow_current = sum(self.closes) / 20

            bullish = (
                fast_previous <= slow_previous and
                fast_current > slow_current
            )

            if bullish and time(9, 45) <= end_time.time() <= time(14, 30):
                self.pending_signal = end_time

        self.bucket = None

    def _try_enter(self, slice: Slice, signal_time: datetime):
        if self.entry_ticket is not None:
            return

        if self.entry_symbol is not None:
            security = self.Securities[self.entry_symbol]
            if security.Holdings.Invested:
                return

        if not slice.OptionChains:
            self.Debug("Skipped entry: no option chain.")
            return

        today = self.Time.date()
        eligible_expirations = []

        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Right != OptionRight.Call:
                    continue

                expiration_date = contract.Expiry.date()
                if (expiration_date - today).days >= 7:
                    eligible_expirations.append(expiration_date)

        if not eligible_expirations:
            self.Debug("Skipped entry: no expiration at least 7 calendar days away.")
            return

        selected_expiry = min(eligible_expirations)
        spy_price = float(self.Securities[self.spy_symbol].Price)
        minimum_strike = 1.01 * spy_price

        candidates = []
        for chain in slice.OptionChains.Values:
            for contract in chain:
                if (
                    contract.Right == OptionRight.Call and
                    contract.Expiry.date() == selected_expiry and
                    float(contract.Strike) >= minimum_strike
                ):
                    candidates.append(contract)

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        candidates.sort(key=lambda c: (float(c.Strike), str(c.Symbol)))
        selected = candidates[0]

        self.entry_symbol = selected.Symbol
        self.entry_ticket = self.MarketOrder(self.entry_symbol, 1)
        self.expiration_stop_day = selected_expiry - timedelta(days=1)
        self.expiration_processed_day = None

    def _process_profit_target(self, slice: Slice):
        if self.entry_symbol is None or self.entry_price is None:
            return
        if self.exit_ticket is not None:
            return

        security = self.Securities[self.entry_symbol]
        if not security.Holdings.Invested:
            return

        contract = self._get_current_contract(slice, self.entry_symbol)
        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("profit target")

    def _process_time_stop(self, slice: Slice):
        if self.entry_symbol is None or self.exit_ticket is not None:
            return

        security = self.Securities[self.entry_symbol]
        if not security.Holdings.Invested:
            return

        if (
            self.expiration_stop_day is not None and
            self.Time.date() == self.expiration_stop_day and
            self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("expiration time stop")

    def _process_expiration_safety(self):
        if self.entry_symbol is None:
            return

        security = self.Securities[self.entry_symbol]
        today = self.Time.date()

        if (
            security.Holdings.Invested and
            self.entry_symbol.ID.Date.date() == today and
            self.expiration_processed_day != today
        ):
            self.expiration_processed_day = today
            if self.exit_ticket is None:
                self._submit_exit("expiration safety liquidation")

    def _submit_exit(self, reason):
        if self.entry_symbol is None:
            return

        if self.exit_ticket is not None:
            return

        if self.entry_ticket is not None and self.entry_ticket.Status == OrderStatus.Submitted:
            self.CancelOrder(self.entry_ticket.OrderId)

        self.exit_ticket = self.Liquidate(self.entry_symbol)
        self.Debug("Exit submitted: " + reason)

    def _get_current_contract(self, slice: Slice, symbol: Symbol):
        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == symbol:
                    return contract
        return None

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None and
            order_event.OrderId == self.entry_ticket.OrderId and
            order_event.Status == OrderStatus.Filled
        ):
            self.entry_price = float(order_event.FillPrice)
            self.Debug(
                "Entered " + str(self.entry_symbol) +
                " at " + str(self.entry_price)
            )

        if (
            self.exit_ticket is not None and
            order_event.OrderId == self.exit_ticket.OrderId and
            order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Exited " + str(self.entry_symbol))
            self.entry_ticket = None
            self.exit_ticket = None
            self.entry_symbol = None
            self.entry_price = None
            self.expiration_stop_day = None

        event_text = str(order_event).lower()
        if "assignment" in event_text or "exercise" in event_text:
            self.Debug("Unexpected option exercise or assignment: " + str(order_event))
