from AlgorithmImports import *
from collections import deque
from datetime import datetime, date, time, timedelta


class SpyBullishCrossoverCallAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            fill_forward=False,
            extended_market_hours=False
        )
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(self.OptionFilter)
        option.PriceModel = OptionPriceModels.BlackScholes()
        self.option_symbol = option.Symbol

        self.fast_closes = deque(maxlen=5)
        self.slow_closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.current_day = None
        self.bucket_date = None
        self.bucket_end = None
        self.bucket_bars = {}

        self.latest_slice = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.expiration_date = None
        self.no_entry_date = None

    def OptionFilter(self, universe):
        return universe.IncludeWeeklys().Strikes(-200, 200).Expiration(0, 730)

    def OnData(self, slice: Slice):
        self.latest_slice = slice
        algorithm_date = self.Time.date()

        self.ProcessExpirationSafety(algorithm_date)
        self.ProcessTimeStop(algorithm_date)
        self.ProcessProfitTarget(slice)

        if self.spy_symbol not in slice.Bars:
            return

        bar = slice.Bars[self.spy_symbol]
        local_end = Extensions.ConvertTo(
            bar.EndTime,
            self.TimeZone
        )

        if local_end.date() != algorithm_date:
            return

        if not self.IsRegularSessionMinute(local_end):
            return

        self.AddMinuteToFiveMinuteBucket(bar, local_end)

    def IsRegularSessionMinute(self, local_time):
        current = local_time.time()
        return time(9, 31) <= current <= time(16, 0)

    def AddMinuteToFiveMinuteBucket(self, bar, local_end):
        bar_date = local_end.date()
        minute = local_end.hour * 60 + local_end.minute

        bucket_end_minutes = ((minute + 4) // 5) * 5
        bucket_end_hour = bucket_end_minutes // 60
        bucket_end_minute = bucket_end_minutes % 60

        if bucket_end_hour != 9 and bucket_end_hour < 16:
            return

        bucket_end = datetime(
            bar_date.year,
            bar_date.month,
            bar_date.day,
            bucket_end_hour,
            bucket_end_minute
        )

        if self.bucket_date is not None and (
            bar_date != self.bucket_date or bucket_end != self.bucket_end
        ):
            self.bucket_bars.clear()

        self.bucket_date = bar_date
        self.bucket_end = bucket_end
        self.bucket_bars[local_end] = bar

        expected_start = bucket_end - timedelta(minutes=4)
        expected_times = [
            expected_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if not all(t in self.bucket_bars for t in expected_times):
            return

        close = self.bucket_bars[expected_times[-1]].Close
        self.bucket_bars.clear()

        self.OnFiveMinuteBar(bucket_end, close)

    def OnFiveMinuteBar(self, bar_end, close):
        self.slow_closes.append(close)
        self.fast_closes.append(close)

        if len(self.fast_closes) < 5 or len(self.slow_closes) < 20:
            return

        fast = sum(self.fast_closes) / 5.0
        slow = sum(self.slow_closes) / 20.0

        bullish_cross = (
            self.previous_fast is not None and
            self.previous_slow is not None and
            self.previous_fast <= self.previous_slow and
            fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        local_end_time = bar_end.time()
        eligible = time(9, 45) <= local_end_time <= time(14, 30)

        if not bullish_cross or not eligible:
            return

        self.TryEnterCall()

    def HasOptionHolding(self):
        return (
            self.held_option is not None and
            self.Portfolio[self.held_option].Invested
        )

    def EntryOrderOpen(self):
        return (
            self.entry_ticket is not None and
            self.entry_ticket.Status in [
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            ]
        )

    def TryEnterCall(self):
        today = self.Time.date()

        if today == self.no_entry_date:
            return

        if self.HasOptionHolding() or self.EntryOrderOpen():
            return

        if self.latest_slice is None:
            self.Debug("Skipped entry: current Slice unavailable.")
            return

        if not self.latest_slice.OptionChains.ContainsKey(self.option_symbol):
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        chain = self.latest_slice.OptionChains[self.option_symbol]
        minimum_expiry = today + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least 7 calendar days away.")
            return

        selected_expiration = expirations[0]

        spy_price = self.Securities[self.spy_symbol].Price
        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiration
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        candidates.sort(key=lambda contract: (
            contract.Strike,
            str(contract.Symbol)
        ))

        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Entry submitted: {} expiry {} strike {:.2f}".format(
                selected.Symbol,
                selected_expiration,
                selected.Strike
            )
        )

    def ProcessProfitTarget(self, slice):
        if not self.HasOptionHolding():
            return

        if self.exit_ticket is not None and self.exit_ticket.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ]:
            return

        if self.entry_price is None:
            return

        symbol = self.held_option
        if not slice.BidQuoteBars.ContainsKey(symbol):
            return
        if not slice.AskQuoteBars.ContainsKey(symbol):
            return

        bid = slice.BidQuoteBars[symbol].Close
        ask = slice.AskQuoteBars[symbol].Close

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self.CancelOpenExitOrder()
            quantity = -self.Portfolio[symbol].Quantity
            if quantity != 0:
                self.exit_ticket = self.MarketOrder(symbol, quantity)
                self.Debug(
                    "Profit-target exit submitted: {} midpoint {:.4f}".format(
                        symbol, midpoint
                    )
                )

    def ProcessTimeStop(self, algorithm_date):
        if not self.HasOptionHolding():
            return

        if self.expiration_date is None:
            return

        stop_date = self.expiration_date - timedelta(days=1)

        if algorithm_date != stop_date:
            return

        if self.Time.time() < time(15, 45):
            return

        self.SubmitLiquidation("expiration-eve time stop")

    def ProcessExpirationSafety(self, algorithm_date):
        if not self.HasOptionHolding():
            return

        if self.expiration_date is None:
            return

        if algorithm_date >= self.expiration_date:
            self.no_entry_date = algorithm_date
            self.SubmitLiquidation("expiration safety liquidation")

    def SubmitLiquidation(self, reason):
        if self.held_option is None:
            return

        if self.exit_ticket is not None and self.exit_ticket.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ]:
            return

        self.CancelOpenExitOrder()

        quantity = -self.Portfolio[self.held_option].Quantity
