class SpyLongCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute, dataNormalizationMode=DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(self.OptionFilter)

        self.fast = RollingWindow[float](5)
        self.slow = RollingWindow[float](20)

        self.minute_buckets = defaultdict(list)
        self.latest_chain = None

        self.entry_ticket = None
        self.entry_symbol = None
        self.entry_price = None
        self.exit_ticket = None
        self.exit_reason = None

        self.blocked_expiration_date = None
        self.last_processed_bar_end = None

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy_symbol),
            self.TimeRules.At(16, 0),
            self.ExpirationSafetyCheck
        )

    def OptionFilter(self, universe):
        return universe.IncludeWeeklys().Strikes(-100, 100).Expiration(0, 365)

    def OnData(self, slice):
        if slice.OptionChains:
            for _, chain in slice.OptionChains.items():
                self.latest_chain = chain

        self.HandleExpirationProcessing(slice)
        self.HandleMinuteExit(slice)

        if self.entry_ticket is not None and not self.entry_ticket.Status.IsOpen():
            self.entry_ticket = None

        if self.entry_symbol is None and self.entry_ticket is None:
            if self.last_processed_bar_end is not None:
                self.TryEntry(slice)

        bar = slice.Bars.get(self.spy_symbol)
        if bar is not None:
            self.ProcessMinuteBar(bar)

    def ProcessMinuteBar(self, bar):
        eastern = Extensions.ConvertTo(
            bar.EndTime,
            self.TimeZone,
            DateTimeZoneProviders.TZDB["America/New_York"]
        )

        local_date = eastern.date()
        local_time = eastern.time()

        if local_time < time(9, 30) or local_time > time(16, 0):
            return

        bucket_minute = (local_time.minute // 5) * 5
        bucket_start = datetime.combine(
            local_date,
            time(local_time.hour, bucket_minute)
        )

        bucket_key = bucket_start
        self.minute_buckets[bucket_key].append(bar)

        if local_time.minute % 5 != 0:
            return

        bars = self.minute_buckets.pop(bucket_key, [])
        if len(bars) != 5:
            return

        bars.sort(key=lambda x: x.EndTime)

        consolidated = TradeBar(
            bucket_start + timedelta(minutes=5),
            self.spy_symbol,
            bars[0].Open,
            max(x.High for x in bars),
            min(x.Low for x in bars),
            bars[-1].Close,
            sum(x.Volume for x in bars),
            timedelta(minutes=5)
        )

        self.ProcessFiveMinuteBar(consolidated)

    def ProcessFiveMinuteBar(self, bar):
        bar_end = bar.EndTime
        if self.last_processed_bar_end == bar_end:
            return

        self.last_processed_bar_end = bar_end

        previous_fast = self.fast[0] if self.fast.IsReady else None
        previous_slow = self.slow[0] if self.slow.IsReady else None

        self.fast.Add(bar.Close)
        self.slow.Add(bar.Close)

        if not (self.fast.IsReady and self.slow.IsReady):
            return

        current_fast = sum(self.fast) / self.fast.Count
        current_slow = sum(self.slow) / self.slow.Count

        if previous_fast is None or previous_slow is None:
            return

        bullish_cross = (
            previous_fast <= previous_slow and
            current_fast > current_slow
        )

        eastern = Extensions.ConvertTo(
            bar_end,
            self.TimeZone,
            DateTimeZoneProviders.TZDB["America/New_York"]
        )

        if bullish_cross and time(9, 45) <= eastern.time() <= time(14, 30):
            self.pending_entry_bar_end = bar_end

    def TryEntry(self, slice):
        if not hasattr(self, "pending_entry_bar_end"):
            return

        if self.pending_entry_bar_end != self.last_processed_bar_end:
            return

        del self.pending_entry_bar_end

        if self.entry_symbol is not None or self.entry_ticket is not None:
            return

        if self.blocked_expiration_date == self.Time.date():
            return

        if self.latest_chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        today = self.Time.date()
        eligible_expirations = sorted({
            contract.Expiry.date()
            for contract in self.latest_chain
            if contract.Expiry.date() >= today + timedelta(days=7)
        })

        if not eligible_expirations:
            self.Debug("Skipped entry: no expiration at least 7 calendar days away.")
            return

        selected_expiry = eligible_expirations[0]
        spy_price = self.Securities[self.spy_symbol].Price

        candidates = [
            contract for contract in self.latest_chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= 1.01 * spy_price
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        candidates.sort(key=lambda c: (c.Strike, str(c.Symbol)))
        selected = candidates[0]

        self.entry_symbol = selected.Symbol
        self.entry_ticket = self.MarketOrder(self.entry_symbol, 1, tag="Entry")
        self.Debug(f"Entry submitted: {self.entry_symbol}")

    def HandleMinuteExit(self, slice):
        if self.entry_symbol is None:
            return

        security = self.Securities[self.entry_symbol]
        holding = security.Holdings

        if not holding.Invested:
            return

        eastern = Extensions.ConvertTo(
            self.Time,
            self.TimeZone,
            DateTimeZoneProviders.TZDB["America/New_York"]
        )

        if self.entry_price is not None:
            quote = slice.QuoteBars.get(self.entry_symbol)
            if quote is not None:
                bid = quote.Bid.Close
                ask = quote.Ask.Close

                if bid > 0 and ask > 0:
                    midpoint = (bid + ask) / 2
                    if midpoint >= 1.5 * self.entry_price:
                        self.SubmitExit("Profit target")
                        return

        expiry_date = security.Symbol.ID.Date.date()
        if eastern.date() == expiry_date - timedelta(days=1) and eastern.time() >= time(15, 45):
            self.SubmitExit("Expiration time stop")

    def SubmitExit(self, reason):
        if self.exit_ticket is not None and self.exit_ticket.Status.IsOpen():
            return

        quantity = -self.Portfolio[self.entry_symbol].Quantity
        if quantity == 0:
            return

        self.exit_reason = reason
        self.exit_ticket = self.MarketOrder(self.entry_symbol, quantity, tag=reason)
        self.Debug(f"Exit submitted: {reason} for {self.entry_symbol}")

    def HandleExpirationProcessing(self, slice):
        if self.entry_symbol is None:
            return

        expiry_date = self.Securities[self.entry_symbol].Symbol.ID.Date.date()
        today = self.Time.date()

        if today == expiry_date:
            self.blocked_expiration_date = today
            if self.Portfolio[self.entry_symbol].Invested:
                self.SubmitExit("Expiration safety liquidation")

    def ExpirationSafetyCheck(self):
        if self.entry_symbol is None:
            return

        expiry_date = self.Securities[self.entry_symbol].Symbol.ID.Date.date()
        if self.Time.date() >= expiry_date and self.Portfolio[self.entry_symbol].Invested:
            self.blocked_expiration_date = self.Time.date()
            self.SubmitExit("Expiration safety liquidation")

    def OnOrderEvent(self, order_event):
        if order_event.Status != OrderStatus.Filled:
            return

        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            self.entry_price = order_event.FillPrice
            self.Debug(
                f"Entry filled: {self.entry_symbol}, "
                f"price={self.entry_price}"
            )

        elif self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            self.Debug(f"Exit filled: {self.exit_reason}, {self.entry_symbol}")
            self.entry_symbol = None
            self.entry_price = None
            self.exit_ticket = None
            self.exit_reason = None

    def OnAssignmentOrder(self, assignment_event):
        self.Debug(f"Unexpected option exercise or assignment: {assignment_event}")

