        threshold = 1.01 * self.Securities[self.spy].Price

        candidates = [
            contract
            for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= threshold
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(f"Entry submitted: {selected.Symbol}")

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.entry_price = order_event.FillPrice
            self.held_symbol = order_event.Symbol
            self.entry_ticket = None

            self.Debug(
                f"Entry filled: {order_event.Symbol} "
                f"@ {order_event.FillPrice}"
            )

        elif (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug(
                f"Exit filled: {order_event.Symbol} "
                f"@ {order_event.FillPrice}"
            )

            self.exit_ticket = None
            self.held_symbol = None
            self.entry_price = None

    def ProcessProfitTarget(self, slice: Slice):
        if (
            self.held_symbol is None
            or self.entry_price is None
            or self.exit_ticket is not None
        ):
            return

        chain = slice.OptionChains.get(self.option.Symbol)
        if chain is None:
            return

        contract = next(
            (
                contract
                for contract in chain
                if contract.Symbol == self.held_symbol
            ),
            None
        )

        if contract is None:
            return

        if contract.BidPrice <= 0 or contract.AskPrice <= 0:
            return

        midpoint = (contract.BidPrice + contract.AskPrice) / 2

        if midpoint >= 1.5 * self.entry_price:
            self.SubmitExit("50% profit target")

    def TimeStop(self):
        if self.held_symbol is None or self.exit_ticket is not None:
            return

        expiry_date = self.Securities[
            self.held_symbol
        ].Symbol.ID.Date.date()

        prior_trading_day = expiry_date - timedelta(days=1)

        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(
            prior_trading_day
        ):
            prior_trading_day -= timedelta(days=1)

        if self.Time.date() == prior_trading_day:
            self.SubmitExit("pre-expiration time stop")

    def ProcessExpiration(self):
        if self.held_symbol is None:
            return

        expiry_date = self.Securities[
            self.held_symbol
        ].Symbol.ID.Date.date()

        if self.Time.date() >= expiry_date:
            self.no_entry_date = self.Time.date()

            if self.exit_ticket is None:
                self.SubmitExit("expiration safeguard")

    def SubmitExit(self, reason):
        if self.held_symbol is None or self.exit_ticket is not None:
            return

        for order in self.Transactions.GetOpenOrders(self.held_symbol):
            self.Transactions.CancelOrder(order.Id)

        quantity = -self.Portfolio[self.held_symbol].Quantity

        if quantity != 0:
            self.exit_ticket = self.MarketOrder(
                self.held_symbol,
                quantity
            )
            self.Debug(f"Exit submitted: {reason}")

    def OnAssignmentOrder(self, assignment_event):
        self.Debug(
            f"Unexpected option exercise or assignment: {assignment_event}"
        )

