                    )
                    self.SubmitLiquidation()

        if self.IsOptionPositionOpen() and not self.skip_expiration_processing_today:
            self.EvaluateProfitTarget(slice)

        self.skip_expiration_processing_today = False

    def OnFiveMinuteBar(self, sender, bar: TradeBar):
        if bar.Symbol != self.spy.Symbol:
            return

        current_time = bar.EndTime.time()

        # The consolidator naturally aligns the first regular-session bar
        # from 09:30 through 09:35 New York time.
        if current_time < time(9, 35):
            return

