            self.Debug("Skipped call selection: no qualifying call at selected expiration.")
            return

        candidates.sort(key=lambda c: (c.Strike, str(c.Symbol)))
        selected = candidates[0]

        self.entry_symbol = selected.Symbol
        self.expiration_date = selected.Expiry.date()
        self.entry_price = None

        ticket = self.MarketOrder(
            self.entry_symbol,
            1,
            tag="bullish five-minute crossover entry"
        )
        self.entry_order_id = ticket.OrderId

    def SubmitExit(self, reason):
        if self.entry_symbol is None:
            return

        quantity = self.Portfolio[self.entry_symbol].Quantity
        if quantity == 0:
            return

        if self.exit_order_id is not None:
            return

        self.CancelOpenExitOrders()

        ticket = self.MarketOrder(
            self.entry_symbol,
            -quantity,
            tag=reason
        )
        self.exit_order_id = ticket.OrderId
        self.Debug("Submitted exit for {}: {}".format(self.entry_symbol, reason))

    def OnOrderEvent(self, order_event):
        if order_event.Status != OrderStatus.Filled:
            return

        if self.entry_order_id == order_event.OrderId:
            self.entry_price = order_event.FillPrice
            self.Debug(
                "Entered {} at {:.4f}".format(
                    self.entry_symbol,
                    self.entry_price
                )
            )
            self.entry_order_id = None
            return

        if self.exit_order_id == order_event.OrderId:
            self.Debug(
                "Exited {} at {:.4f}".format(
                    self.entry_symbol,
                    order_event.FillPrice
                )
            )
            self.exit_order_id = None
            self.entry_symbol = None
            self.entry_price = None
            self.expiration_date = None

    def ProcessExpirationSafety(self):
        if self.entry_symbol is None or self.expiration_date is None:
            return

        if self.last_processed_expiration_date == self.expiration_date:
            return

        if self.Time.date() >= self.expiration_date:
            self.last_processed_expiration_date = self.expiration_date
            self.no_entry_today = True

            if self.Portfolio[self.entry_symbol].Invested:
                self.SubmitExit("expiration safety liquidation")

    def IsExpirationTimeStop(self):
        if self.expiration_date is None:
            return False

        previous_trading_day = self.GetPreviousTradingDay(self.expiration_date)

        return (
            self.Time.date() == previous_trading_day
            and self.Time.time() >= time(15, 45)
        )

    def GetPreviousTradingDay(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy_symbol].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def GetCurrentContract(self, slice, symbol):
        for chain in slice.OptionChains.Values:
            if symbol in chain.Contracts:
                return chain.Contracts[symbol]

        return None

    def CancelOpenExitOrders(self):
        if self.exit_order_id is not None:
            self.Transactions.CancelOrder(self.exit_order_id)
            self.exit_order_id = None

    def OnAssignmentOrder(self, assignment_order):
        self.Debug(
            "Unexpected option assignment/exercise handling: {}".format(
                assignment_order
            )
        )
